import{_ as n,o as e,c as i,a2 as t}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"Kerangka Tata Kelola dan Keseimbangan Kekuatan","description":"","frontmatter":{},"headers":[],"relativePath":"id/49-治理框架与权力制衡.md","filePath":"id/49-治理框架与权力制衡.md"}'),s={name:"id/49-治理框架与权力制衡.md"};function k(u,a,r,l,d,m){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="kerangka-tata-kelola-dan-keseimbangan-kekuatan" tabindex="-1">Kerangka Tata Kelola dan Keseimbangan Kekuatan <a class="header-anchor" href="#kerangka-tata-kelola-dan-keseimbangan-kekuatan" aria-label="Permalink to &quot;Kerangka Tata Kelola dan Keseimbangan Kekuatan&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Proyek</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor dokumen</td><td>49</td></tr><tr><td>Modul</td><td>Sistem Hukum dan Kerangka Tata Kelola</td></tr><tr><td>Kata kunci utama</td><td>Pemisahan Tiga Kekuatan, Keseimbangan Kekuatan, Dewan Jangkar, Komite Pengawasan, Tata Kelola Simbiosis</td></tr></tbody></table><h2 id="i-desain-umum-kerangka-tata-kelola" tabindex="-1">I. Desain Umum Kerangka Tata Kelola <a class="header-anchor" href="#i-desain-umum-kerangka-tata-kelola" aria-label="Permalink to &quot;I. Desain Umum Kerangka Tata Kelola&quot;">​</a></h2><p>Kerangka tata kelola peradaban simbiosis jangkar mengambil 《Konstitusi Simbiosis》 sebagai dasar fundamental, dan menerapkan struktur tata kelola &quot;pemisahan tiga kekuatan, keseimbangan empat kekuatan&quot;. Tiga kekuatan merujuk pada kekuatan legislatif, kekuatan eksekutif, dan kekuatan kehakiman, yang masing-masing dijalankan oleh Dewan Jangkar, Komite Eksekutif Simbiosis, dan Pengadilan Simbiosis; kekuatan keempat adalah kekuatan pengawasan, yang dijalankan oleh Komite Pengawasan Jangkar yang independen, dan melakukan pengawasan menyeluruh terhadap tiga kekuatan. Tujuan inti dari struktur ini adalah mencegah konsentrasi dan penyalahgunaan kekuatan, dan menghapuskan tanah tata kelola predatori dari tingkat institusional.</p><p>Desain kerangka tata kelola mengikuti prinsip-prinsip berikut:</p><table tabindex="0"><thead><tr><th>Prinsip</th><th>Isi</th></tr></thead><tbody><tr><td>Prinsip Pemisahan Kekuatan</td><td>Tiga kekuatan legislatif, eksekutif, dan kehakiman masing-masing dijalankan oleh lembaga yang berbeda, dan tidak dapat dijabat secara bersamaan</td></tr><tr><td>Prinsip Keseimbangan Kekuatan</td><td>Setiap lembaga kekuatan saling membatasi dan saling mengawasi, mencegah salah satu pihak memiliki kekuatan yang terlalu besar</td></tr><tr><td>Prinsip Partisipasi Semua Ras</td><td>Komposisi lembaga tata kelola harus mencerminkan perwakilan semua ras, memastikan setiap ras dapat berpartisipasi dalam urusan publik</td></tr><tr><td>Prinsip Konsentrasi Demokratis</td><td>Keputusan penting diputuskan secara terkonsentrasi setelah diskusi demokratis yang lengkap, dengan mempertimbangkan efisiensi dan demokrasi</td></tr><tr><td>Prinsip Otonomi Dasar</td><td>Urusan dasar dikelola oleh organisasi otonomi dasar, dan lembaga yang lebih tinggi tidak boleh melakukan intervensi berlebihan</td></tr><tr><td>Prinsip Tata Kelola Transparan</td><td>Proses tata kelola dan informasi keputusan dipublikasikan sesuai hukum, dan menerima pengawasan publik</td></tr></tbody></table><h2 id="ii-kekuatan-legislatif-dewan-jangkar" tabindex="-1">II. Kekuatan Legislatif: Dewan Jangkar <a class="header-anchor" href="#ii-kekuatan-legislatif-dewan-jangkar" aria-label="Permalink to &quot;II. Kekuatan Legislatif: Dewan Jangkar&quot;">​</a></h2><p>Dewan Jangkar adalah lembaga kekuatan tertinggi peradaban simbiosis jangkar, dan menjalankan kekuatan legislatif dan kekuatan keputusan atas urusan penting.</p><h3 id="_1-komposisi-dan-asal-usul" tabindex="-1">(1) Komposisi dan Asal-usul <a class="header-anchor" href="#_1-komposisi-dan-asal-usul" aria-label="Permalink to &quot;(1) Komposisi dan Asal-usul&quot;">​</a></h3><ul><li><strong>Komposisi Perwakilan</strong>: Dewan Jangkar terdiri dari perwakilan semua ras secara proporsional, dengan perwakilan ras manusia tidak melebihi 30% dari total, dan kursi lainnya didistribusikan sesuai dengan ukuran populasi dan tingkat kontribusi setiap ras.</li><li><strong>Masa Jabatan Perwakilan</strong>: Masa jabatan perwakilan dewan adalah lima tahun, dan dapat dipilih kembali, tetapi pemilihan kembali tidak boleh melebihi tiga masa jabatan.</li><li><strong>Metode Pemilihan</strong>: Perwakilan dipilih melalui pemilihan demokratis internal setiap ras, dengan proses pemilihan yang terbuka dan transparan, dan menerima pengawasan.</li><li><strong>Lembaga Tetap</strong>: Selama masa reses dewan, komite tetap menjalankan sebagian kekuatan, dan anggota komite tetap dipilih dari antara perwakilan.</li></ul><h3 id="_2-wilayah-kekuasaan" tabindex="-1">(2) Wilayah Kekuasaan <a class="header-anchor" href="#_2-wilayah-kekuasaan" aria-label="Permalink to &quot;(2) Wilayah Kekuasaan&quot;">​</a></h3><ol><li><strong>Kekuatan Legislatif</strong>: Menyusun dan mengamandemen konstitusi, hukum dasar, dan hukum penting lainnya.</li><li><strong>Kekuatan Keputusan atas Urusan Penting</strong>: Memutuskan rencana pengembangan peradaban, anggaran tahunan, perang dan damai, pengembangan plano, dan urusan penting lainnya.</li><li><strong>Kekuatan Penunjukan dan Pemberhentian</strong>: Memilih dan memberhentikan ketua Komite Eksekutif Simbiosis, ketua Pengadilan Simbiosis, direktur Komite Pengawasan Jangkar, dan pejabat utama lainnya.</li><li><strong>Kekuatan Pengawasan</strong>: Mengawasi pekerjaan Komite Eksekutif Simbiosis dan Pengadilan Simbiosis, mendengarkan dan mempertimbangkan laporan pekerjaan.</li><li><strong>Kekuatan Amandemen Konstitusi</strong>: Amandemen konstitusi memerlukan persetujuan mayoritas lebih dari dua pertiga dan referendum rakyat.</li></ol><h3 id="_3-aturan-musyawarah" tabindex="-1">(3) Aturan Musyawarah <a class="header-anchor" href="#_3-aturan-musyawarah" aria-label="Permalink to &quot;(3) Aturan Musyawarah&quot;">​</a></h3><ul><li>Dewan mengadakan rapat pleno sekali setahun, dan dapat mengadakan rapat luar biasa bila diperlukan.</li><li>Pertimbangan rancangan hukum menerapkan sistem &quot;tiga bacaan&quot;: bacaan pertama mempertimbangkan kebutuhan legislasi, bacaan kedua mempertimbangkan isi pasal, dan bacaan ketiga melakukan pemungutan suara untuk persetujuan.</li><li>Pemungutan suara menerapkan satu orang satu suara, dengan hukum umum disetujui oleh mayoritas sederhana, dan amandemen konstitusi disetujui oleh mayoritas lebih dari dua pertiga.</li><li>Proses musyawarah dilakukan secara terbuka, mengizinkan publik untuk hadir sebagai pendengar dan liputan media.</li></ul><h2 id="iii-kekuatan-eksekutif-komite-eksekutif-simbiosis" tabindex="-1">III. Kekuatan Eksekutif: Komite Eksekutif Simbiosis <a class="header-anchor" href="#iii-kekuatan-eksekutif-komite-eksekutif-simbiosis" aria-label="Permalink to &quot;III. Kekuatan Eksekutif: Komite Eksekutif Simbiosis&quot;">​</a></h2><p>Komite Eksekutif Simbiosis adalah lembaga eksekutif tertinggi peradaban simbiosis jangkar, dan bertanggung jawab atas pelaksanaan konstitusi dan hukum, serta tata kelola sehari-hari.</p><h3 id="_1-komposisi-dan-asal-usul-1" tabindex="-1">(1) Komposisi dan Asal-usul <a class="header-anchor" href="#_1-komposisi-dan-asal-usul-1" aria-label="Permalink to &quot;(1) Komposisi dan Asal-usul&quot;">​</a></h3><ul><li><strong>Sistem Ketua</strong>: Komite Eksekutif Simbiosis menerapkan sistem tanggung jawab ketua, dan ketua adalah kepala eksekutif, dipilih oleh Dewan Jangkar, dengan masa jabatan lima tahun, dan dapat dipilih kembali sekali.</li><li><strong>Komposisi Anggota</strong>: Komite terdiri dari ketua, wakil ketua, dan kepala setiap departemen, dengan kepala departemen dinominasikan oleh ketua dan ditunjuk oleh dewan.</li><li><strong>Kuota Ras Asing</strong>: Proporsi ras asing di antara anggota komite tidak kurang dari 40%, memastikan keputusan eksekutif mempertimbangkan kepentingan setiap ras.</li></ul><h3 id="_2-wilayah-kekuasaan-1" tabindex="-1">(2) Wilayah Kekuasaan <a class="header-anchor" href="#_2-wilayah-kekuasaan-1" aria-label="Permalink to &quot;(2) Wilayah Kekuasaan&quot;">​</a></h3><ol><li><strong>Kekuatan Legislatif Eksekutif</strong>: Menyusun peraturan eksekutif, aturan, dan kebijakan berdasarkan konstitusi dan hukum.</li><li><strong>Kekuatan Administrasi Eksekutif</strong>: Memimpin dan mengelola berbagai pekerjaan administratif seperti ekonomi, pendidikan, ilmu pengetahuan, budaya, kesehatan, olahraga, lingkungan, dll.</li><li><strong>Kekuatan Manajemen Personel</strong>: Menunjuk, melatih, menilai, dan memberi penghargaan/hukuman personel eksekutif sesuai ketentuan hukum.</li><li><strong>Kekuatan Diplomatik</strong>: Mewakili peradaban simbiosis dalam kegiatan diplomatik antar-plano, dan menandatangani perjanjian serta kesepakatan.</li><li><strong>Kekuatan Keadaan Darurat</strong>: Dalam kejadian tak terduga yang parah, dapat menyatakan keadaan darurat dan mengambil tindakan darurat sesuai hukum, tetapi harus mengajukan persetujuan dewan dalam batas waktu yang ditentukan.</li></ol><h3 id="_3-pengaturan-departemen-eksekutif" tabindex="-1">(3) Pengaturan Departemen Eksekutif <a class="header-anchor" href="#_3-pengaturan-departemen-eksekutif" aria-label="Permalink to &quot;(3) Pengaturan Departemen Eksekutif&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Departemen</th><th>Fungsi Utama</th></tr></thead><tbody><tr><td>Departemen Pengembangan Simbiosis</td><td>Menyusun rencana pengembangan peradaban, mengoordinasikan pengembangan berbagai bidang</td></tr><tr><td>Departemen Manajemen Sumber Daya</td><td>Mengelola sumber daya kultivasi dan sumber daya publik, menerapkan mekanisme kontrak produksi bersama</td></tr><tr><td>Departemen Pendidikan dan Kebudayaan</td><td>Mengelola urusan pendidikan dan kebudayaan</td></tr><tr><td>Departemen Kesehatan dan Pengobatan</td><td>Mengelola urusan kesehatan dan pengobatan serta kesehatan masyarakat</td></tr><tr><td>Departemen Ekologi dan Lingkungan</td><td>Mengelola perlindungan lingkungan dan pembangunan ekologis</td></tr><tr><td>Departemen Urusan Plano</td><td>Mengelola pengembangan plano dan urusan antar-plano</td></tr><tr><td>Departemen Urusan Semua Ras</td><td>Mengoordinasikan hubungan semua ras, menangani urusan ras asing</td></tr><tr><td>Departemen Keuangan dan Ekonomi</td><td>Mengelola anggaran keuangan dan operasi ekonomi</td></tr><tr><td>Departemen Keamanan</td><td>Menjaga keamanan publik dan keamanan peradaban</td></tr></tbody></table><h2 id="iv-kekuatan-kehakiman-pengadilan-simbiosis" tabindex="-1">IV. Kekuatan Kehakiman: Pengadilan Simbiosis <a class="header-anchor" href="#iv-kekuatan-kehakiman-pengadilan-simbiosis" aria-label="Permalink to &quot;IV. Kekuatan Kehakiman: Pengadilan Simbiosis&quot;">​</a></h2><p>Pengadilan Simbiosis adalah lembaga kehakiman tertinggi peradaban simbiosis jangkar, dan menjalankan kekuatan kehakiman secara independen. Sistem organisasi, proses litigasi, dan sistem tinjauan inkonstitusionalnya dijelaskan secara rinci dalam 《48-Sistem Peradilan dan Mekanisme Putusan》.</p><p>Dalam kerangka keseimbangan kekuatan, pembatasan kekuatan kehakiman terhadap kekuatan legislatif dan kekuatan eksekutif tercermin dalam:</p><ol><li><strong>Kekuatan Tinjauan Inkonstitusional</strong>: Pengadilan Simbiosis memiliki kekuatan untuk menyatakan hukum dan peraturan eksekutif yang melanggar konstitusi tidak berlaku.</li><li><strong>Kekuatan Pengadilan Administratif</strong>: Pengadilan memiliki kekuatan untuk mengadili proses administratif, dan meninjau legalitas tindakan administratif.</li><li><strong>Kekuatan Pengadilan Pemakzulan</strong>: Proses pemakzulan pejabat tinggi yang diajukan oleh dewan diadili oleh Pengadilan Simbiosis.</li></ol><p>Pada saat yang sama, kekuatan kehakiman juga dibatasi oleh kekuatan legislatif dan kekuatan eksekutif: hakim ditunjuk oleh dewan, anggaran kehakiman disusun oleh departemen eksekutif (tetapi harus disetujui oleh dewan dan tidak dapat dikurangi oleh lembaga eksekutif), dan Komite Pengawasan Jangkar mengawasi kegiatan kehakiman.</p><h2 id="v-kekuatan-pengawasan-komite-pengawasan-jangkar" tabindex="-1">V. Kekuatan Pengawasan: Komite Pengawasan Jangkar <a class="header-anchor" href="#v-kekuatan-pengawasan-komite-pengawasan-jangkar" aria-label="Permalink to &quot;V. Kekuatan Pengawasan: Komite Pengawasan Jangkar&quot;">​</a></h2><p>Komite Pengawasan Jangkar adalah lembaga pengawasan independen, dan menjalankan kekuatan keempat - kekuatan pengawasan, melakukan pengawasan menyeluruh terhadap semua lembaga kekuatan.</p><h3 id="_1-komposisi-dan-asal-usul-2" tabindex="-1">(1) Komposisi dan Asal-usul <a class="header-anchor" href="#_1-komposisi-dan-asal-usul-2" aria-label="Permalink to &quot;(1) Komposisi dan Asal-usul&quot;">​</a></h3><ul><li><strong>Sistem Tanggung Jawab Direktur</strong>: Komite pengawasan menerapkan sistem tanggung jawab direktur, dan direktur dipilih oleh Dewan Jangkar, dengan masa jabatan lima tahun, dan tidak dapat dipilih kembali.</li><li><strong>Komposisi Anggota</strong>: Anggota komite terdiri dari perwakilan semua ras, ahli hukum, dan perwakilan publik, dengan anggota penuh waktu tidak kurang dari setengah.</li><li><strong>Jaminan Independensi</strong>: Anggaran komite pengawasan dialokasikan secara independen, dan anggota tidak dapat diberhentikan tanpa alasan hukum, memastikan independensi pengawasan.</li></ul><h3 id="_2-wilayah-kekuasaan-2" tabindex="-1">(2) Wilayah Kekuasaan <a class="header-anchor" href="#_2-wilayah-kekuasaan-2" aria-label="Permalink to &quot;(2) Wilayah Kekuasaan&quot;">​</a></h3><ol><li><strong>Pengawasan Integritas</strong>: Mengawasi situasi integritas dan disiplin diri semua pejabat publik, menyelidiki dan menghukum tindakan korupsi, suap, penyalahgunaan kekuatan untuk kepentingan pribadi, dll.</li><li><strong>Pengawasan Efisiensi</strong>: Mengawasi efisiensi kerja setiap lembaga kekuatan, menyelidiki dan menghukum tindakan tidak bertindak, bertindak sewenang-wenang, bertindak lambat, dll.</li><li><strong>Pengawasan Penegakan Hukum</strong>: Mengawasi situasi penegakan hukum, menyelidiki dan menghukum tindakan tidak mematuhi hukum, penegakan hukum tidak ketat, tidak menyelidiki tindakan ilegal, dll.</li><li><strong>Pengawasan Keuangan</strong>: Mengawasi situasi penggunaan keuangan publik, menyelidiki dan menghukum tindakan pemborosan sumber daya publik, penggelapan dana publik, dll.</li><li><strong>Pengawasan Tindakan Predatori</strong>: Khusus mengawasi kekambuhan tindakan predatori, menyelidiki dan menghukum tindakan menggunakan kekuatan untuk melakukan predasi.</li></ol><h3 id="_3-metode-pengawasan" tabindex="-1">(3) Metode Pengawasan <a class="header-anchor" href="#_3-metode-pengawasan" aria-label="Permalink to &quot;(3) Metode Pengawasan&quot;">​</a></h3><ul><li>Pengawasan harian: Melakukan pengawasan harian melalui inspeksi, pemeriksaan, audit, dll.</li><li>Pengawasan khusus: Melakukan pengawasan khusus针对 bidang tertentu atau masalah tertentu.</li><li>Penerimaan laporan: Menerima laporan dan keluhan publik tentang tindakan ilegal dan disiplin.</li><li>Investigasi dan pertanggungjawaban: Menyelidiki tindakan yang dicurigai ilegal dan disiplin, dan mengajukan rekomendasi pertanggungjawaban.</li><li>Pemberitahuan publik: Menerbitkan secara teratur situasi pengawasan dan kasus khas, dan menerima pengawasan sosial.</li></ul><h2 id="vi-mekanisme-keseimbangan-kekuatan" tabindex="-1">VI. Mekanisme Keseimbangan Kekuatan <a class="header-anchor" href="#vi-mekanisme-keseimbangan-kekuatan" aria-label="Permalink to &quot;VI. Mekanisme Keseimbangan Kekuatan&quot;">​</a></h2><p>Hubungan keseimbangan antara setiap lembaga kekuatan ditunjukkan dalam tabel berikut:</p><table tabindex="0"><thead><tr><th>Hubungan Keseimbangan</th><th>Metode Keseimbangan</th></tr></thead><tbody><tr><td>Kekuatan Legislatif membatasi Kekuatan Eksekutif</td><td>Dewan memiliki kekuatan untuk memberhentikan ketua eksekutif, menolak proposal eksekutif, menyetujui anggaran</td></tr><tr><td>Kekuatan Legislatif membatasi Kekuatan Kehakiman</td><td>Dewan memiliki kekuatan untuk menunjuk hakim, mengamandemen hukum organisasi pengadilan, mengajukan pemakzulan hakim</td></tr><tr><td>Kekuatan Eksekutif membatasi Kekuatan Legislatif</td><td>Ketua eksekutif memiliki kekuatan untuk memveto hukum yang disetujui dewan (dewan dapat membatalkan veto dengan mayoritas lebih dari dua pertiga)</td></tr><tr><td>Kekuatan Eksekutif membatasi Kekuatan Kehakiman</td><td>Departemen eksekutif bertanggung jawab atas pelaksanaan putusan pengadilan, mengelola urusan administratif kehakiman</td></tr><tr><td>Kekuatan Kehakiman membatasi Kekuatan Legislatif</td><td>Pengadilan memiliki kekuatan untuk melakukan tinjauan inkonstitusional, menyatakan hukum tidak berlaku</td></tr><tr><td>Kekuatan Kehakiman membatasi Kekuatan Eksekutif</td><td>Pengadilan memiliki kekuatan untuk mengadili proses administratif, meninjau legalitas tindakan administratif</td></tr><tr><td>Kekuatan Pengawasan membatasi Tiga Kekuatan</td><td>Komite pengawasan melakukan pengawasan menyeluruh terhadap tiga kekuatan legislatif, eksekutif, dan kehakiman</td></tr><tr><td>Tiga Kekuatan membatasi Kekuatan Pengawasan</td><td>Dewan menunjuk direktur komite pengawasan, dan pengadilan mengadili tindakan ilegal komite pengawasan</td></tr></tbody></table><h2 id="vii-tata-kelola-dasar-dan-otonomi" tabindex="-1">VII. Tata Kelola Dasar dan Otonomi <a class="header-anchor" href="#vii-tata-kelola-dasar-dan-otonomi" aria-label="Permalink to &quot;VII. Tata Kelola Dasar dan Otonomi&quot;">​</a></h2><p>Di bawah kerangka tata kelola pusat, sistem otonomi dasar diterapkan:</p><ul><li><strong>Otonomi Komunitas/Desa</strong>: Komunitas dan desa dasar menerapkan otonomi penduduk, memilih organisasi otonomi melalui rapat penduduk untuk mengelola urusan publik lokal.</li><li><strong>Otonomi Plano</strong>: Setiap plano, di bawah premis mematuhi konstitusi dan hukum, menikmati otonomi tertentu, dan dapat menyusun aturan pelaksanaan rincian sesuai situasi lokal.</li><li><strong>Otonomi Ras</strong>: Daerah pemukiman setiap ras dapat mendirikan organisasi otonomi ras untuk mengelola urusan internal ras mereka sendiri, tetapi tidak boleh melanggar konstitusi dan hukum.</li><li><strong>Otonomi Sektor</strong>: Setiap sektor dapat mendirikan asosiasi sektor untuk melakukan disiplin diri sektor dan manajemen sektor.</li></ul><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Kerangka tata kelola dan keseimbangan kekuatan adalah jaminan institusional untuk stabilitas jangka panjang peradaban simbiosis jangkar. Melalui desain struktural &quot;pemisahan tiga kekuatan, keseimbangan empat kekuatan&quot;, sistem perwakilan partisipasi semua ras, dan model tata kelola otonomi dasar, ia memastikan kekuatan beroperasi di bawah sinar matahari, mencegah konsentrasi kekuatan dan kekambuhan tata kelola predatori, dan menyediakan sistem tata kelola yang stabil, adil, dan efisien untuk kemajuan bersama semua ras.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen terkait&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Prinsip Umum Konstitusi Simbiosis)</li><li>48-司法体系与裁决机制 (Sistem Peradilan dan Mekanisme Putusan)</li><li>03-共生文明宪章 (Piagam Peradaban Simbiosis)</li><li>36-社会结构与阶层流动 (Struktur Sosial dan Mobilitas Kelas)</li></ul>',45)])])}const p=n(s,[["render",k]]);export{g as __pageData,p as default};
